import { Component, Input, OnInit } from '@angular/core';
import { ModalController } from '@ionic/angular';
import { ICourseImageModel } from 'src/app/data/model/course/CourseVideoModel';
import { HostListener } from '@angular/core';

@Component({
  templateUrl: './admin-photo-gallery-modal-page.component.html',
  styleUrls: ['./admin-photo-gallery-modal-page.component.scss']
})
export class AdminPhotoGalleryModalPageComponent implements OnInit {

  photo = '';
  index = 1;
  @Input() gallery: ICourseImageModel[] = [];

  constructor(public modalController: ModalController) { }

  @HostListener('window:popstate', ['$event'])
  onPopState(event) {
    this.modalController.dismiss();
  }

  ngOnInit(): void {

    this.photo = this.gallery[0].url;
  }

  dismiss(data?: any) {

    if (data != null) {

      this.modalController.dismiss({ code: data, id: this.gallery[this.index - 1].id });
    } else {

      this.modalController.dismiss();
    }
  }

  next() {

    if (this.index < this.gallery.length) {

      this.photo = this.gallery[this.index].url;
      this.index++;
    }
  }

  back() {

    if (this.index > 1) {

      this.index--;
      this.photo = this.gallery[this.index - 1].url;
    }
  }
}
